theorem extracted_1.{u_2} {G : Type u_2} [inst : AddCommGroup G] {G₂ : AddSubgroup G} (H' : AddSubgroup (G ⧸ G₂)) :
  let H := G ⧸ G₂;
  let φ := mk' G₂;
  let N := AddSubgroup.comap φ H';
  G₂ ≤ N →
    let H'' := AddSubgroup.map (mk' G₂) N;
    H' = H'' →
      let H := G ⧸ G₂;
      let φ := mk' G₂;
      let N := AddSubgroup.comap φ H';
      ∃ e, ∀ (x : G), e ((mk' H') (φ x)) = (mk' N) x := by
  let e1 : H ⧸ H'' ≃+ G ⧸ N := quotientQuotientEquivQuotient _ _ h1
    let e2 := quotientAddEquivOfEq h2
    set e := e2.trans e1
    use e
    intro x
    convert (quotientQuotientEquivQuotientAux_mk_mk _ _ h1 x) using 1

theorem extracted_1.{u_2} {G : Type u_2} [inst : AddCommGroup G] {G₂ : AddSubgroup G} (H' : AddSubgroup (G ⧸ G₂)) :
  let H := G ⧸ G₂;
  let φ := mk' G₂;
  let N := AddSubgroup.comap φ H';
  G₂ ≤ N →
    let H'' := AddSubgroup.map (mk' G₂) N;
    H' = H'' := by
  change H' = AddSubgroup.map (mk' G₂) N
      rw [AddSubgroup.map_comap_eq, AddMonoidHom.range_eq_top_of_surjective _ (mk'_surjective G₂)]
      simp

theorem extracted_1.{u_2} {G : Type u_2} [inst : AddCommGroup G] {G₂ : AddSubgroup G} (H' : AddSubgroup (G ⧸ G₂)) :
  let H := G ⧸ G₂;
  let φ := mk' G₂;
  let N := AddSubgroup.comap φ H';
  G₂ ≤ N →
    let H := G ⧸ G₂;
    let φ := mk' G₂;
    let N := AddSubgroup.comap φ H';
    ∃ e, ∀ (x : G), e ((mk' H') (φ x)) = (mk' N) x := by
  set H'' := AddSubgroup.map (mk' G₂) N
    have h2 : H' = H'' := by
      change H' = AddSubgroup.map (mk' G₂) N
      rw [AddSubgroup.map_comap_eq, AddMonoidHom.range_eq_top_of_surjective _ (mk'_surjective G₂)]
      simp
    let e1 : H ⧸ H'' ≃+ G ⧸ N := quotientQuotientEquivQuotient _ _ h1
    let e2 := quotientAddEquivOfEq h2
    set e := e2.trans e1
    use e
    intro x
    convert (quotientQuotientEquivQuotientAux_mk_mk _ _ h1 x) using 1

theorem extracted_1.{u_2} {G : Type u_2} [inst : AddCommGroup G] {G₂ : AddSubgroup G} (H' : AddSubgroup (G ⧸ G₂)) :
  let H := G ⧸ G₂;
  let φ := mk' G₂;
  let N := AddSubgroup.comap φ H';
  G₂ ≤ N := by
  intro x hx
      rw [← eq_zero_iff] at hx
      have : φ x = 0 := hx
      simp [N, this, AddSubgroup.zero_mem H']

